-- One-off seed of the history table. Only the latest value per voter is known,
-- so these rows are marked "backfill" and their timestamp is the last change.
INSERT INTO "rating_history" ("photo_id", "user_id", "score", "at", "source")
SELECT "photo_id", "user_id", "score", "updated_at", 'backfill' FROM "ratings";
